def gen(rng):
    def fmt(n, k, edges):
        return f"{n} {k}" + ''.join(f"\n{u} {v}" for u, v in edges)
    def relabel(n, edges):
        perm = list(range(n))
        rng.shuffle(perm)
        out = []
        for u, v in edges:
            a, b = perm[u], perm[v]
            out.append((a, b) if rng.random() < 0.5 else (b, a))
        rng.shuffle(out)
        return out
    def rand_tree(n, shape=0):
        e = []
        for v in range(1, n):
            if shape == 0:
                p = rng.randrange(v)
            elif shape == 1:
                p = max(0, v - rng.randint(1, 3))
            else:
                p = rng.randrange(max(1, v // 2 + 1))
            e.append((p, v))
        return e
    tests = [fmt(1, 0, []), fmt(1, 5, []), fmt(2, 1, [(0, 1)]), fmt(2, 0, [(0, 1)]), fmt(3, 1, [(0, 1), (1, 2)]), fmt(4, 1, [(0, 1), (0, 2), (0, 3)])]
    for n in (3, 4, 6, 8, 12, 20, 30):
        for _ in range(3):
            e = relabel(n, rand_tree(n, rng.randrange(3)))
            tests.append(fmt(n, rng.randint(0, 6), e))
    N = 100000
    path = [(i, i + 1) for i in range(N - 1)]
    tests.append(fmt(N, 20000, relabel(N, path)))
    tests.append(fmt(N, 49999, relabel(N, path)))
    tests.append(fmt(N, 10**9, relabel(N, path)))
    tests.append(fmt(N, 3, relabel(N, rand_tree(N, 0))))
    tests.append(fmt(N, 2, [(0, i) for i in range(1, N)]))
    tests.append(fmt(N, 1, [(0, i) for i in range(1, N)]))
    tests.append(fmt(N, 100, relabel(N, rand_tree(N, 1))))
    tests.append(fmt(N, 1000, relabel(N, rand_tree(N, 1))))
    return tests

